//! Oracle tier: reads artifacts regenerated by `scripts/regen-fixtures.py`
//! (tools/fixtures/langlibelk-language*.toml, docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
#[path = "../examples/import-url-oracle.rs"]
#[allow(dead_code)]
mod oracle;
#[test]
fn pinned_go_html_and_import_url_predicate() {
    let fixture: serde_json::Value =
        serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/import-url.json")).unwrap();
    let requests = fixture["requests"].as_array().unwrap();
    let reference = fixture["reference"].as_array().unwrap();
    assert_eq!(requests.len(), reference.len());
    for (request, expected) in requests.iter().zip(reference) {
        assert_eq!(
            oracle::evaluate(request.as_str().unwrap()),
            *expected,
            "{request}"
        );
    }
}
